import { useDebugger } from "@solid-devtools/debugger/bundled";
function clone(data) {
  return typeof data === "object" ? JSON.parse(JSON.stringify(data)) : data;
}
function separate(data, callback) {
  queueMicrotask(() => {
    const v = clone(data);
    queueMicrotask(() => callback(v));
  });
}
function Devtools(props) {
  const debug = useDebugger();
  debug.emit("ResetState");
  onCleanup(() => debug.emit("InspectNode", null));
  const {
    bridge,
    Devtools: Frontend
  } = createDevtools();
  bridge.output.listen((e) => {
    separate(e.details, (details) => debug.emit(e.name, details));
  });
  debug.listen((e) => {
    separate(e.details, (details) => bridge.input.emit(e.name, details));
  });
  return createComponent(Frontend, props);
}

